// Le o JSON do classificador, junta com os dados da conversa e guarda o texto
// que o bot vai enviar (para reconhecer o eco do proprio bot depois).

const d = $('Reconferir Vendedor').first().json;
const respostaBot = $('Agente FAQ').first().json.output || '';

let c = { temperatura: 'frio', interesse: 'Contato inicial', preco: null, precisa_humano: false };

try {
  const bruto = $input.first().json.choices?.[0]?.message?.content;
  if (bruto) {
    const parsed = JSON.parse(bruto);
    c = {
      temperatura: ['quente', 'morno', 'frio'].includes(parsed.temperatura) ? parsed.temperatura : 'frio',
      interesse: parsed.interesse || 'Contato inicial',
      preco: parsed.preco && parsed.preco !== 'null' ? parsed.preco : null,
      precisa_humano: parsed.precisa_humano === true,
    };
  }
} catch (e) {
  // Se a classificacao falhar, seguimos com o padrao em vez de derrubar o atendimento.
  console.log('Falha ao classificar, usando padrao:', e.message);
}

// Guarda o texto enviado: quando ele voltar pelo webhook com fromMe=true,
// o Normalizar Entrada reconhece que foi o bot e nao o vendedor.
const norm = (s) => String(s || '').trim().toLowerCase().replace(/\s+/g, ' ');
const store = $getWorkflowStaticData('global');
store.conversas = store.conversas || {};
const est = store.conversas[d.telefone] || { textos_bot: [], ids_bot: [] };
est.textos_bot = [...(est.textos_bot || []), norm(respostaBot)].slice(-10);
est.ultima_resposta_bot_em = Date.now();
est.atualizado_em = Date.now();
store.conversas[d.telefone] = est;

return [{
  json: {
    slug: d.slug,
    nome_negocio: d.nome_negocio,
    supabase_url: d.supabase_url,
    evolution_url: d.evolution_url,
    evolution_instance: d.evolution_instance,
    telefone: d.telefone,
    nome: d.nome,
    canal: d.canal,
    mensagem_cliente: d.mensagem,
    resposta_bot: respostaBot,
    temperatura: c.temperatura,
    interesse: c.interesse,
    preco: c.preco,
    precisa_humano: c.precisa_humano,
  },
}];

// Guarda o id da mensagem que a Evolution acabou de enviar.
// E a forma mais confiavel de reconhecer o eco do proprio bot no webhook.

const tel = $('Processar Classificação').first().json.telefone;
const id = $input.first().json?.key?.id;

if (id) {
  const store = $getWorkflowStaticData('global');
  store.conversas = store.conversas || {};
  const est = store.conversas[tel] || { textos_bot: [], ids_bot: [] };
  est.ids_bot = [...(est.ids_bot || []), id].slice(-10);
  store.conversas[tel] = est;
}

return $input.all();
